function feedMediaLoading(media,message='Loading video…',show=true){const card=media.closest('.aam-discovery-card,.aam-social-feed-item');if(!card)return;let indicator=card.querySelector(':scope > .aam-feed-video-loading')||card.querySelector('.aam-discovery-player > .aam-feed-video-loading');if(!indicator){indicator=document.createElement('span');indicator.className='aam-feed-video-loading';indicator.setAttribute('aria-live','polite');card.appendChild(indicator);}indicator.textContent=message;indicator.hidden=!show;}
function bindFeedMediaState(media){if(media.dataset.aamFeedStateBound==='1')return;media.dataset.aamFeedStateBound='1';if(media.tagName==='VIDEO'){media.addEventListener('loadstart',()=>feedMediaLoading(media,'Loading video…',true));media.addEventListener('waiting',()=>feedMediaLoading(media,'Buffering video…',true));media.addEventListener('stalled',()=>feedMediaLoading(media,'Buffering video…',true));media.addEventListener('canplay',()=>feedMediaLoading(media,'',false));media.addEventListener('playing',()=>feedMediaLoading(media,'',false));media.addEventListener('error',()=>feedMediaLoading(media,'Video unavailable — swipe to continue',true));}else if(media.tagName==='IFRAME'){media.addEventListener('load',()=>{if(media.src&&media.src!=='about:blank')feedMediaLoading(media,'',false);});}}
function setupDiscoveryPlayback(){const box=document.getElementById('aamDiscoveryFeed');if(!box)return;if(!box.dataset.infiniteBound){box.dataset.infiniteBound='1';box.addEventListener('scroll',maybeLoadMoreDiscovery,{passive:true});}if(aamDiscoveryObserver)aamDiscoveryObserver.disconnect();aamDiscoveryObserver=new IntersectionObserver(entries=>{for(const entry of entries){const media=entry.target,active=entry.isIntersecting&&entry.intersectionRatio>=.65;media.dataset.aamFeedActive=active?'1':'0';bindFeedMediaState(media);if(media.tagName==='VIDEO'){if(active){media.muted=true;media.preload='auto';if(media.networkState===HTMLMediaElement.NETWORK_EMPTY)media.load();const attempt=media.play();if(attempt&&typeof attempt.catch==='function')attempt.catch(()=>{if(media.isConnected&&media.dataset.aamFeedActive==='1'&&!media.paused)return;if(media.isConnected&&media.dataset.aamFeedActive==='1')feedMediaLoading(media,'Tap play to start video',true);});const next=media.closest('.aam-discovery-card,.aam-social-feed-item')?.nextElementSibling?.querySelector('video');if(next){bindFeedMediaState(next);next.preload='metadata';if(next.networkState===HTMLMediaElement.NETWORK_EMPTY)next.load();}}else{media.pause();if(media.preload==='auto')media.preload='metadata';}}else if(media.tagName==='IFRAME'){if(active){if(!media.src&&media.dataset.src){feedMediaLoading(media,'Loading video…',true);media.src=media.dataset.src;}}else if(media.src&&media.src!=='about:blank'){media.src='about:blank';}}}},{root:box,threshold:[0,.25,.65,1]});box.querySelectorAll('video,iframe.aam-discovery-embed').forEach(v=>aamDiscoveryObserver.observe(v));requestAnimationFrame(()=>{if(box.isConnected&&box.scrollHeight<=box.clientHeight+700)maybeLoadMoreDiscovery();});}
async function fetchDiscovery({query='',append=false}={}){if(aamDiscoveryBusy)return;aamDiscoveryBusy=true;const box=document.getElementById('aamDiscoveryFeed'),status=document.getElementById('aamDiscoveryStatus');if(!append){aamDiscoveryItems=[];aamDiscoveryEmptyPages=0;aamDiscoveryHasMore=true;aamDiscoveryPage=1;aamDiscoveryCursor='';}if(status)status.textContent=append?'Loading more videos…':'Finding entertainment videos…';try{const p=new URLSearchParams({mode:query?'search':'feed',limit:'8',page:String(append?++aamDiscoveryPage:1)});if(query)p.set('q',query);if(append&&aamDiscoveryCursor)p.set('cursor',aamDiscoveryCursor);const d=await api('/.netlify/functions/social-video-discovery?'+p.toString());aamDiscoveryCursor='';const incoming=d.items||[];const seen=new Set(aamDiscoveryItems.map(x=>x.id));const fresh=incoming.filter(x=>!seen.has(x.id));aamDiscoveryItems.push(...fresh);if(fresh.length)aamDiscoveryEmptyPages=0;else if(append)aamDiscoveryEmptyPages++;renderDiscovery(append?fresh:aamDiscoveryItems,append);const available=(d.providers||[]).filter(x=>x.available);aamDiscoveryHasMore=!!d.hasMore;if(status)status.textContent=available.length?'Videos from '+available.map(x=>x.name).join(', '):'Creator videos are temporarily unavailable. Your uploaded posts are still available.';if(append&&(!d.hasMore||aamDiscoveryEmptyPages>=2)){aamDiscoveryHasMore=false;if(status)status.textContent='You have reached the available videos for now.';}}catch(e){if(append)aamDiscoveryPage=Math.max(0,aamDiscoveryPage-1);if(status)status.textContent='Could not load videos. Pull down to retry.';if(box&&!append)box.innerHTML='<div class="aam-discovery-empty">Video sources are temporarily unavailable.</div>';}finally{aamDiscoveryBusy=false;}}
