async function comments(id){const box=document.getElementById('aamComments-'+id);if(!box)return;try{const d=await api('/.netlify/functions/social-interactions?post_id='+encodeURIComponent(id));box.innerHTML=d.comments_disabled?'<p class="aam-social-muted">Comments are disabled for this post.</p>':'<div class="aam-social-comments">'+(d.comments||[]).map(c=>'<p><strong>'+esc(c.creator?.display_name||'Friend')+'</strong> '+esc(c.body)+'</p>').join('')+'<textarea class="aam-social-field" id="aamCommentText-'+id+'" placeholder="Write a comment…"></textarea><button class="aam-social-btn" onclick="AAMSocial.comment(\''+esc(id)+'\')">Send comment</button></div>';}catch(e){box.textContent=e.message;}}
