  let audioPath=null;const audio=window.aamSelectedPostAudio;if(audio){if(status)status.textContent='Uploading sound…';const audioSigned=await api('/.netlify/functions/social-feed','POST',{action:'sign_audio_upload',mime_type:audio.type});const audioUpload=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(audioSigned.path,audioSigned.token,audio,{contentType:audio.type,upsert:false});if(audioUpload.error)throw audioUpload.error;audioPath=audioSigned.path;uploadedPaths.push(audioPath);}
