async function chat(){window.aamStopChatTyping?.();if(window.aamChatListTypingTimer){clearInterval(window.aamChatListTypingTimer);window.aamChatListTypingTimer=null;}document.getElementById('aamChatBody')?.blur();discardVoiceNoteOnNavigation();stopAllVoicePlayback();document.body.classList.remove('aam-chat-fullscreen-active');document.documentElement.classList.remove('aam-chat-fullscreen-active');if(window.aamChatPresenceTimer){clearInterval(window.aamChatPresenceTimer);window.aamChatPresenceTimer=null;}if(window.aamCallPollTimer){clearInterval(window.aamCallPollTimer);window.aamCallPollTimer=null;}loadingPage('Loading your chats…','chat');if(window.aamChatRefreshTimer){clearInterval(window.aamChatRefreshTimer);window.aamChatRefreshTimer=null;window.aamActiveChatId=null;}if(window.aamChatTypingTimer){clearInterval(window.aamChatTypingTimer);window.aamChatTypingTimer=null;}try{const d=await api('/.netlify/functions/social-chat');mount('<section class="aam-social-card aam-social-chat-inbox"><header class="aam-chat-inbox-header"><h2>Chats</h2><button class="aam-social-btn secondary" onclick="AAMSocial.messageAdmin()">Contact All Ads Manager</button></header><div class="aam-chat-add-by-id"><button type="button" class="aam-social-btn" onclick="AAMSocial.openAddChatById()" aria-label="Add chat by profile ID">＋ Add by profile ID</button><div class="aam-chat-add-form" id="aamChatAddForm" hidden><label for="aamChatProfileId">Enter profile ID</label><div><input id="aamChatProfileId" class="aam-social-field" maxlength="48" autocomplete="off" placeholder="Profile ID"><button type="button" class="aam-social-btn" onclick="AAMSocial.lookupChatProfile()">Find</button></div><div id="aamChatProfileResult" aria-live="polite"></div></div></div><div class="aam-chat-inbox-list">'+(d.conversations||[]).map(c=>'<button class="aam-social-chat-row" data-conversation-id="'+esc(c.id)+'" onclick="AAMSocial.openChat(&quot;'+esc(c.id)+'&quot;)"><strong>'+esc(c.other?.display_name||'Friend')+(c.other?.is_group?' · Community':'')+'</strong><small class="aam-chat-row-status">'+(c.other?.is_typing?'typing…':(c.other?.is_group?formatCount(c.other.member_count)+' members · '+(c.other.group_role==='admin'?'Group admin':'Member'):(c.other?.last_seen_at&&Date.now()-new Date(c.other.last_seen_at).getTime()<120000?'Online':(c.other?.last_seen_at?'Last seen '+new Date(c.other.last_seen_at).toLocaleString():'Offline'))))+'</small><span>'+(c.last_message?esc(c.last_message.body||'Media message'):'Start a conversation')+'</span></button>').join('')+'</div><p class="aam-social-muted aam-chat-inbox-hint">Add someone using their profile ID, or open an existing conversation.</p></section>','chat');if(window.aamChatListTypingTimer)clearInterval(window.aamChatListTypingTimer);window.aamChatListTypingTimer=setInterval(refreshChatListTyping,3500);}catch(e){mount('<div class="aam-social-card"><h2>Chats</h2><p>'+esc(e.message)+'</p></section>','chat');}}
async function refreshChatListTyping(){try{if(!document.querySelector('.aam-social-chat-row'))return;const d=await api('/.netlify/functions/social-chat');for(const c of d.conversations||[]){const row=document.querySelector('.aam-social-chat-row[data-conversation-id="'+c.id+'"]'),label=row?.querySelector('.aam-chat-row-status');if(label&&c.other?.is_typing)label.textContent='typing…';else if(label&&label.textContent==='typing…')label.textContent=c.other?.is_group?formatCount(c.other.member_count)+' members · '+(c.other.group_role==='admin'?'Group admin':'Member'):(c.other?.last_seen_at&&Date.now()-new Date(c.other.last_seen_at).getTime()<120000?'Online':(c.other?.last_seen_at?'Last seen '+new Date(c.other.last_seen_at).toLocaleString():'Offline'));}}catch(e){}}
function messageAdmin(){window.aamStopChatTyping?.();if(window.aamChatListTypingTimer){clearInterval(window.aamChatListTypingTimer);window.aamChatListTypingTimer=null;}document.getElementById('aamChatBody')?.blur();discardVoiceNoteOnNavigation();if(window.aamCallPollTimer){clearInterval(window.aamCallPollTimer);window.aamCallPollTimer=null;}if(window.aamChatTypingTimer){clearInterval(window.aamChatTypingTimer);window.aamChatTypingTimer=null;}if(window.aamChatPresenceTimer){clearInterval(window.aamChatPresenceTimer);window.aamChatPresenceTimer=null;}if(window.aamChatRefreshTimer){clearInterval(window.aamChatRefreshTimer);window.aamChatRefreshTimer=null;window.aamActiveChatId=null;}if(typeof window.supportPage==='function')window.supportPage();else notice('Administrator contact is not available right now.');}
function openAddChatById(){const box=document.getElementById("aamChatAddForm");if(!box)return;box.hidden=!box.hidden;if(!box.hidden)document.getElementById("aamChatProfileId")?.focus();}
async function lookupChatProfile(){const field=document.getElementById("aamChatProfileId"),result=document.getElementById("aamChatProfileResult"),id=String(field?.value||"").trim();if(!id)return notice("Enter a profile ID first.");if(result)result.innerHTML="<p class=\"aam-social-muted\">Finding profile…</p>";try{const d=await api("/.netlify/functions/social-discover?public_id="+encodeURIComponent(id));const p=d.profile;if(!p)throw new Error("No profile was found with that ID.");if(result)result.innerHTML="<div class=\"aam-chat-found-profile\">"+(p.avatar_url?"<img src=\""+esc(p.avatar_url)+"\" alt=\"\">":"<span class=\"aam-chat-found-avatar\">✦</span>")+"<div><strong>"+esc(p.display_name||"Customer")+"</strong><small>Profile ID: "+esc(p.public_profile_id||id)+"</small></div></div><div class=\"aam-chat-found-actions\"><button type=\"button\" class=\"aam-social-btn secondary\" onclick=\"AAMSocial.follow(\'"+esc(p.customer_id)+"\')\">Follow</button><button type=\"button\" class=\"aam-social-btn\" onclick=\"AAMSocial.startChat(\'"+esc(p.customer_id)+"\')\">Message</button></div>";}catch(e){if(result)result.innerHTML="<p class=\"aam-social-muted\">"+esc(e.message||"Could not find that profile.")+"</p>";}}
async function startChat(id){try{const d=await api('/.netlify/functions/social-chat','POST',{action:'start',target_customer_id:id});openChat(d.conversation_id);}catch(e){notice(e.message);}}
function chatReactionHtml(reactions=[]){const groups=new Map();for(const r of reactions){const g=groups.get(r.emoji)||{emoji:r.emoji,count:0,mine:false};g.count++;if(r.customer_id===customer())g.mine=true;groups.set(r.emoji,g);}return [...groups.values()].map(g=>'<button type="button" class="aam-chat-reaction-chip '+(g.mine?'mine':'')+'" aria-label="'+g.count+' '+esc(g.emoji)+' reactions" onclick="AAMSocial.reactToMessage(this.closest(\'[data-message-id]\').dataset.messageId,\''+g.emoji+'\')">'+esc(g.emoji)+' <span>'+g.count+'</span></button>').join('');}
function updateChatReactionDisplay(el,reactions){if(!el)return;let box=el.querySelector('.aam-chat-reaction-list');const html=chatReactionHtml(reactions);if(!html){box?.remove();return;}if(!box){box=document.createElement('div');box.className='aam-chat-reaction-list';el.appendChild(box);}box.innerHTML=html;}
function voiceTime(seconds){if(!Number.isFinite(seconds)||seconds<0)return '0:00';const n=Math.floor(seconds);return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
function voiceWaveHtml(id){let seed=0;for(const ch of String(id||'voice'))seed=(seed*31+ch.charCodeAt(0))>>>0;let bars='';for(let i=0;i<36;i++){seed=(seed*1664525+1013904223)>>>0;const h=4+(seed%15);bars+='<i style="--bar-height:'+h+'px"></i>';}return bars;}
let aamVoicePlaybackRequest=0;
function stopAllVoicePlayback(){aamVoicePlaybackRequest++;document.querySelectorAll('.aam-chat-voice-player audio').forEach(audio=>{if(!audio.paused)audio.pause();updateVoicePlayback(audio);});}
function updateVoicePlayback(audio){const player=audio?.closest('.aam-chat-voice-player');if(!player)return;const duration=Number.isFinite(audio.duration)?audio.duration:0,elapsed=audio.currentTime||0;const progress=duration?Math.min(100,elapsed/duration*100):0;player.style.setProperty('--aam-voice-progress',progress+'%');const bars=player.querySelectorAll('.aam-chat-voice-wave i');bars.forEach((bar,index)=>bar.classList.toggle('played',index<Math.ceil(bars.length*progress/100)));const time=player.querySelector('.aam-chat-voice-time');if(time)time.textContent=voiceTime(audio.ended?duration:elapsed)+' / '+voiceTime(duration);const button=player.querySelector('.aam-chat-voice-play');if(button){button.textContent=audio.paused||audio.ended?'▶':'Ⅱ';button.setAttribute('aria-label',audio.paused||audio.ended?'Play voice note':'Pause voice note');}}
async function toggleVoicePlayback(button){const player=button?.closest('.aam-chat-voice-player'),audio=player?.querySelector('audio');if(!audio)return;const request=++aamVoicePlaybackRequest;document.querySelectorAll('.aam-chat-voice-player audio').forEach(other=>{if(other!==audio&&!other.paused){other.pause();updateVoicePlayback(other);}});if(audio.paused||audio.ended){if(audio.ended)audio.currentTime=0;try{await audio.play();if(request!==aamVoicePlaybackRequest){audio.pause();}}catch(_){if(request===aamVoicePlaybackRequest)notice('Could not play this voice note. Tap again to retry.');}}else audio.pause();updateVoicePlayback(audio);}
function chatMessageHtml(m){return '<div class="aam-social-message '+(m.sender_id===customer()?'mine':'')+'" data-message-id="'+esc(m.id)+'" data-sent-at="'+esc(m.created_at)+'"><strong>'+esc(m.creator?.display_name||'Friend')+'</strong><p class="aam-chat-message-body">'+esc(m.body||((m.message_type==='voice')?'Voice note':'Media message'))+'</p><small>'+new Date(m.created_at).toLocaleString()+(m.edited_at?' · edited':'')+'</small>'+(m.sender_id===customer()?(m.read_by?.length?'<small class="aam-read" aria-label="Read">✓✓</small>':'<small class="aam-message-status" aria-label="Sent">✓</small>'):'')+(m.message_type==='voice'&&m.media_url?'<div class="aam-chat-voice-player"><button type="button" class="aam-chat-voice-play" aria-label="Play voice note" onclick="AAMSocial.toggleVoicePlayback(this)">▶</button><div class="aam-chat-voice-track"><div class="aam-chat-voice-wave">'+voiceWaveHtml(m.id)+'</div><small class="aam-chat-voice-time">0:00 / --:--</small></div><audio preload="none" src="'+esc(m.media_url)+'" onloadedmetadata="AAMSocial.updateVoicePlayback(this)" ontimeupdate="AAMSocial.updateVoicePlayback(this)" onplay="AAMSocial.updateVoicePlayback(this)" onpause="AAMSocial.updateVoicePlayback(this)" onended="AAMSocial.updateVoicePlayback(this)"></audio></div>':m.message_type==='image'&&m.media_url?'<img class="aam-social-chat-media" loading="lazy" src="'+esc(m.media_url)+'" alt="Shared image">':m.message_type==='video'&&m.media_url?'<video class="aam-social-chat-media" controls playsinline preload="none" src="'+esc(m.media_url)+'"></video>':m.message_type==='shared_post'?'<button class="aam-social-btn secondary" onclick="AAMSocial.viewSharedPost(&quot;'+esc(m.shared_post_id||'')+'&quot;)">View shared post</button>':'')+(m.reactions?.length?'<div class="aam-chat-reaction-list">'+chatReactionHtml(m.reactions)+'</div>':'')+'</div>';}
document.addEventListener('contextmenu',e=>{if(e.target.closest('input,textarea,[contenteditable="true"]'))return;e.preventDefault();});
function openChatInfo(){const state=window.aamChatInfoState;if(!state)return;const profile=state.profile||{},conversation=state.conversation||{},name=profile.display_name||conversation.title||'Conversation',avatar=profile.avatar_url?'<img class="aam-chat-info-avatar" src="'+esc(profile.avatar_url)+'" alt="">':'<span class="aam-chat-info-avatar fallback">✦</span>';mount('<section class="aam-social-card aam-chat-info-screen"><header class="aam-chat-info-header"><button type="button" class="aam-social-btn secondary aam-chat-back" aria-label="Back to conversation" onclick="AAMSocial.openChat(&quot;'+esc(state.id)+'&quot;)">←</button><h2>Chat Info</h2></header><div class="aam-chat-info-profile">'+avatar+'<h2>'+esc(name)+'</h2><p>'+(conversation.conversation_type==='group'?'Group conversation':'All Ads Manager contact')+'</p></div><div class="aam-chat-info-details"><div><span>Chat type</span><strong>'+esc(conversation.conversation_type==='group'?'Group':'Direct message')+'</strong></div><div><span>Conversation started</span><strong>'+ (conversation.created_at?esc(new Date(conversation.created_at).toLocaleDateString()):'Available in chat history')+'</strong></div></div></section>','chat');}function openChatImageViewer(src){const modal=document.createElement('div');modal.className='aam-chat-image-viewer';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.innerHTML='<header><button type="button" aria-label="Close image">←</button><strong>Photo</strong><div><button type="button" aria-label="Zoom out">−</button><button type="button" aria-label="Zoom in">＋</button></div></header><div class="aam-chat-image-stage"><img alt="Shared photo" src="'+String(src).replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'"></div>';const previousOverflow=document.body.style.overflow,previousFocus=document.activeElement;document.body.appendChild(modal);document.body.style.overflow='hidden';const image=modal.querySelector('img'),closeButton=modal.querySelector('header button[aria-label="Close image"]');let scale=1;const apply=()=>{image.style.transform='scale('+scale+')';};const close=()=>{modal.remove();document.body.style.overflow=previousOverflow;if(previousFocus&&typeof previousFocus.focus==='function')previousFocus.focus();document.removeEventListener('keydown',onKeyDown);};const onKeyDown=e=>{if(e.key==='Escape'){e.preventDefault();close();}};document.addEventListener('keydown',onKeyDown);closeButton.onclick=close;closeButton.focus();modal.querySelector('button[aria-label="Zoom in"]').onclick=()=>{scale=Math.min(4,scale+.35);apply();};modal.querySelector('button[aria-label="Zoom out"]').onclick=()=>{scale=Math.max(1,scale-.35);apply();};let startDistance=0,startScale=1;const stage=modal.querySelector('.aam-chat-image-stage');stage.addEventListener('touchstart',e=>{if(e.touches.length===2){startDistance=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);startScale=scale;}},{passive:true});stage.addEventListener('touchmove',e=>{if(e.touches.length===2&&startDistance){const distance=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);scale=Math.max(1,Math.min(4,startScale*distance/startDistance));apply();}},{passive:true});modal.addEventListener('click',e=>{if(e.target===modal)close();});}document.addEventListener('click',event=>{const image=event.target.closest?.('.aam-social-chat-media');if(image&&image.tagName==='IMG'){event.preventDefault();openChatImageViewer(image.currentSrc||image.src);}});let aamChatLongPressTimer=null,aamChatMenuDismissHandler=null,aamChatMenuReturnFocus=null;
function closeChatMessageMenu(){if(aamChatMenuDismissHandler){document.removeEventListener('pointerdown',aamChatMenuDismissHandler,true);document.removeEventListener('keydown',aamChatMenuDismissHandler,true);document.removeEventListener('scroll',aamChatMenuDismissHandler,true);window.removeEventListener('resize',aamChatMenuDismissHandler);aamChatMenuDismissHandler=null;}document.getElementById('aamChatMessageMenu')?.remove();const target=aamChatMenuReturnFocus;aamChatMenuReturnFocus=null;if(target?.isConnected&&typeof target.focus==='function')target.focus({preventScroll:true});}
function messageMenu(event,id){event?.preventDefault?.();const el=document.querySelector('[data-message-id="'+id+'"]');if(!el)return;closeChatMessageMenu();aamChatMenuReturnFocus=event?.currentTarget?.closest?.('[data-message-id]')||el;const own=el.classList.contains('mine'),created=Number(new Date(el.dataset.sentAt).getTime()),editable=own&&Date.now()-created<=15*60*1000;const menu=document.createElement('div');menu.id='aamChatMessageMenu';menu.className='aam-chat-message-menu';menu.setAttribute('role','group');menu.setAttribute('aria-label','Message actions');menu.innerHTML='<div class="aam-chat-reactions">'+['👍','❤️','😂','😮','😢','🙏'].map(e=>'<button type="button" aria-label="React '+e+'" onclick="AAMSocial.reactToMessage(\''+id+'\',\''+e+'\')">'+e+'</button>').join('')+'</div><div class="aam-chat-menu-actions"><button type="button" onclick="AAMSocial.copyMessage(\''+id+'\')">Copy</button>'+(own?'<button type="button" onclick="AAMSocial.deleteMessage(\''+id+'\')">Delete</button>':'')+(editable?'<button type="button" onclick="AAMSocial.editMessage(\''+id+'\')">Edit</button>':'')+'</div>';document.body.appendChild(menu);aamChatMenuDismissHandler=e=>{if(e.type==='keydown'&&e.key==='Escape'){e.preventDefault();closeChatMessageMenu();return;}if(e.type==='keydown'&&e.key==='Tab'){const buttons=[...menu.querySelectorAll('button:not(:disabled)')];if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(e.type==='pointerdown'&&!menu.contains(e.target)||e.type==='scroll')closeChatMessageMenu();};setTimeout(()=>{if(document.getElementById('aamChatMessageMenu')===menu){document.addEventListener('pointerdown',aamChatMenuDismissHandler,true);document.addEventListener('keydown',aamChatMenuDismissHandler,true);document.addEventListener('scroll',aamChatMenuDismissHandler,true);window.addEventListener('resize',aamChatMenuDismissHandler);}},0);const rect=el.getBoundingClientRect(),gap=8,menuHeight=menu.offsetHeight,menuWidth=menu.offsetWidth;const left=Math.max(gap,Math.min(window.innerWidth-menuWidth-gap,rect.left));const above=rect.top-menuHeight-gap,below=rect.bottom+gap;const top=above>=gap?above:below+menuHeight<=window.innerHeight-gap?below:Math.max(gap,Math.min(window.innerHeight-menuHeight-gap,above));menu.style.left=left+'px';menu.style.top=top+'px';menu.querySelector('button')?.focus({preventScroll:true});}
