async function deleteMessage(id){if(!confirm('Delete this message for both people?'))return;try{await api('/.netlify/functions/social-chat','POST',{action:'delete',message_id:id});closeChatMessageMenu();if(window.aamActiveChatId)await openChat(window.aamActiveChatId);notice('Message deleted.');}catch(e){notice(e.message||'Could not delete this message.');}}
async function editMessage(id){const el=document.querySelector('[data-message-id="'+id+'"]'),body=el?.querySelector('.aam-chat-message-body')?.textContent||'';if(!el)return;const value=prompt('Edit your message:',body);if(value===null||!value.trim())return;try{await api('/.netlify/functions/social-chat','POST',{action:'edit',message_id:id,body:value.trim()});el.querySelector('.aam-chat-message-body').textContent=value.trim();const small=el.querySelector('small');if(small&&!small.textContent.includes('edited'))small.textContent+=' · edited';notice('Message updated.');}catch(e){notice(e.message);}closeChatMessageMenu();}
async function reactToMessage(id,emoji){const el=document.querySelector('[data-message-id="'+id+'"]');if(!el)return;closeChatMessageMenu();try{const d=await api('/.netlify/functions/social-chat','POST',{action:'react',message_id:id,emoji});updateChatReactionDisplay(el,d.reactions||[]);}catch(e){notice(e.message||'Could not save your reaction.');}}
